// Reference-based heritage coaches, in the shared 1100 × 360 train coordinates.
function heritageBogie(x) {
  return `<g transform="translate(${x} 294)"><rect x="-94" y="-8" width="188" height="12" rx="2" fill="#222a28"/>${[-58,58].map(p=>`<g transform="translate(${p} 15)"><circle r="22" fill="url(#steel)" stroke="#202725" stroke-width="2"/><circle r="17" fill="#414843" stroke="#888c7c"/><circle r="9" fill="#28352f"/><circle r="4" fill="#9eaa95"/></g>`).join('')}<path d="M-87 0h174v14l-17 12H43l-17-10h-52l-17 10h-27l-17-12z" fill="#455047" stroke="#748072"/>${[-31,31].map(p=>`<rect x="${p-8}" y="-5" width="16" height="24" rx="3" fill="#26322b"/>${[0,4,8,12,16].map(y=>`<path d="M${p-8} ${y}h16" stroke="#899580" stroke-width="2"/>`).join('')}`).join('')}<path d="M-80 7h160m-160 17h160" stroke="#9b9d89" stroke-width="1.5"/><rect x="-66" y="8" width="16" height="14" rx="3" fill="#687061"/><rect x="50" y="8" width="16" height="14" rx="3" fill="#687061"/></g>`;
}
function heritageChassis() {
  return `<rect x="23" y="282" width="1054" height="12" fill="#242e29"/><path d="M34 294h1031" stroke="#647163" stroke-width="2"/><rect x="343" y="292" width="200" height="28" rx="2" fill="#343e35"/><path d="M352 299h182m-182 7h182" stroke="#65705e"/><rect x="612" y="292" width="133" height="24" rx="2" fill="#2a342c"/>${heritageBogie(219)}${heritageBogie(883)}`;
}
function heritageWindow(x,y,w,h,frame='#dbb329',split=true) {
  return `<g transform="translate(${x} ${y})"><rect width="${w}" height="${h}" rx="7" fill="${frame}" stroke="#9a803d"/><rect x="5" y="5" width="${w-10}" height="${h-10}" rx="4" fill="url(#glass)"/><path d="M8 9h13l-8 ${h-18}H8zm${w-26} 0h18v${h-18}h-10z" fill="#e1d5b3" opacity=".42"/>${split?`<path d="M5 ${h*.46}h${w-10}" stroke="${frame}" stroke-width="4"/>`:''}<path class="window-shine" d="M25 7l-12 ${h-14}h8L33 7z" fill="#e8ece0" opacity=".15"/><path d="M7 6h${w-14}" stroke="#f5e2ac" opacity=".6"/></g>`;
}
function heritageDoor(x,fill,frame) {
  return `<g transform="translate(${x} 82)"><rect width="53" height="195" rx="2" fill="${fill}" stroke="#aaaba1"/>${heritageWindow(10,12,33,68,frame,false)}<path d="M42 97h8" stroke="#dfd6bd" stroke-width="3"/><path d="M5 112v68m44-68v68" stroke="#c7bb96" stroke-width="2"/><path d="M2 202h49m-45 6h41m-36 6h31" stroke="#9eab9b" stroke-width="3"/></g>`;
}
function renderHeritageCar() {
  const arches=Array.from({length:5},(_,i)=>`<path d="M${741+i*39} 245v-9a17 17 0 0 1 34 0v9m-34-4h34m-29-19 23 0"/>`).join('');
  return `${heritageChassis()}<rect x="18" y="70" width="1064" height="215" rx="6" fill="#edeadd" stroke="#7c7669"/><path d="M18 74V62q0-30 31-30h1002q31 0 31 30v12z" fill="url(#metalRoof)" stroke="#7c898b"/><path d="M46 36h1005M23 63h1056" stroke="#f0f0e4" opacity=".5"/><g><path d="M164 30l12-15h156l10 15z" fill="#a4adb0" stroke="#6d7a7c"/><rect x="181" y="12" width="143" height="12" rx="2" fill="#d3d7d4"/><path d="M190 18h123" stroke="#9da7a6"/>${[467,657,849].map(x=>`<path d="M${x} 31l5-8h29l5 8z" fill="#a0aaab" stroke="#748081"/>`).join('')}</g><path d="M19 79h1062" stroke="#d9b126" stroke-width="4"/><rect x="19" y="209" width="1062" height="76" fill="#6c397d"/><path d="M19 229h600l17 18h445v20H19z" fill="#e1b931"/>${Array.from({length:10},(_,i)=>heritageWindow(146+i*80,96,70,108)).join('')}${heritageDoor(55,'#703782','#dbb329')}${heritageDoor(992,'#703782','#dbb329')}<text x="441" y="254" text-anchor="middle" font-family="Arial,sans-serif" font-size="19" letter-spacing="1.8" font-weight="bold" fill="#703881">HÀNH TRÌNH DI SẢN</text><g fill="none" stroke="#e7c452" stroke-width="1.8">${arches}<path d="M735 215h202m-202 30h202"/><path d="M819 205l9-4 8 4-4 4h-9z" fill="#e7c452"/></g><text x="130" y="279" font-family="Arial" font-size="9" fill="#f3d773">HARACO · A 31441</text><circle cx="972" cy="117" r="12" fill="#6e3880" stroke="#dfbb43"/><text x="972" y="115" text-anchor="middle" font-family="Arial" font-size="3.5" fill="#efd875">HÀNH TRÌNH</text><text x="972" y="121" text-anchor="middle" font-family="Arial" font-size="4.5" fill="#efd875">DI SẢN</text><path d="M19 282h1062" stroke="#462b54" stroke-width="3"/>`;
}
function hanoiGate(x,y,scale=1) {
  return `<g transform="translate(${x} ${y}) scale(${scale})" fill="#54392e"><path d="M0 24h14V11h14V3l7 6 9-9 9 9 7-6v8h14v13h14v39H57V46a13 13 0 0 0-26 0v17H0z"/><path d="M14 12q8 2 14-2M60 10q6 4 14 2" stroke="#54392e" stroke-width="5" fill="none"/><path d="M39 12h10v12H39z" fill="#efe0bd"/><path d="M7 43h10v20H7zm64 0h10v20H71z" fill="#efe0bd"/></g>`;
}
function renderHanoiCar() {
  return `${heritageChassis()}<path d="M18 69q0-27 33-37h998q33 10 33 37v216H18z" fill="#e8d7b4" stroke="#7b6551"/><path d="M18 70V62q0-30 31-30h1002q31 0 31 30v8z" fill="#883f2f" stroke="#6f382e"/><path d="M49 37h1002M24 63h1053" stroke="#ba7860" opacity=".55"/>${[270,672].map(x=>`<path d="M${x} 31l8-9h95l8 9z" fill="#773e32"/><path d="M${x+14} 25h82" stroke="#ae735d"/>`).join('')}<path d="M18 178h1064v5H18zm0 14h1064v11H18z" fill="#7a382b"/><path d="M124 274h858l-19 11H143z" fill="#873d2e"/>${Array.from({length:6},(_,i)=>heritageWindow(156+i*91,74,75,54,'#6b5c47',false)).join('')}${Array.from({length:5},(_,i)=>heritageWindow(218+i*91,134,71,37,'#6b5c47',false)).join('')}${Array.from({length:6},(_,i)=>heritageWindow(156+i*91,217,75,56,'#6b5c47',false)).join('')}<rect x="293" y="176" width="391" height="29" fill="#e8d7b4"/><text x="488" y="199" text-anchor="middle" font-family="Georgia,serif" font-size="27" letter-spacing="1" fill="#673c2c">THE HANOI TRAIN</text>${hanoiGate(870,80,.67)}<text x="902" y="140" text-anchor="middle" font-family="Arial,sans-serif" font-size="15" font-weight="bold" fill="#65392c">Ô QUAN CHƯỞNG</text>${hanoiGate(829,163,.68)}${heritageWindow(938,218,42,54,'#6b5c47',false)}${heritageDoor(55,'#e8d7b4','#6b5c47')}${heritageDoor(992,'#e8d7b4','#6b5c47')}<path d="M18 279h119l-9-22H18zm961 0h103l0-22H988z" fill="#343833"/><path d="M129 73v205m852-205v205" stroke="#b9a582" stroke-width="1"/><text x="751" y="272" font-family="Arial" font-size="8" fill="#794e39">VNR · THE HANOI TRAIN</text>`;
}
